import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {packContext} from './context-packet.js';
const s=(id,text,priority,required)=>({id,text,priority,required});
assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), {text:'',bytes:0,included:[],omitted:[]});
assert.throws(()=>packContext([], Number.MAX_SAFE_INTEGER + 1), Error);
assert.throws(()=>packContext([s('bad','x',Number.MAX_SAFE_INTEGER + 1,false)], 0), Error);
assert.deepEqual(packContext([s('__proto__','\0雪',2,false),s('later','x',1,false)], 20), {
  text:'### "later"\nx\n', bytes:14, included:['later'], omitted:['__proto__']
});
for (const bad of [null, {}, new Array(1), [null], [{id:'x',text:'x',priority:0}], [s('x','x',0,false),s('x','y',1,false)]]) {
  assert.throws(()=>packContext(bad,0), Error);
}
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'context-packet-'));
try {
  const input=path.join(dir,'input.json');
  fs.writeFileSync(input, JSON.stringify({sections:[s('a','é',0,true)],maxBytes:13}));
  let result=spawnSync(process.execPath,['context-packet.js',input],{encoding:'utf8'});
  assert.equal(result.status,0); assert.equal(result.stderr,'');
  assert.deepEqual(JSON.parse(result.stdout),packContext([s('a','é',0,true)],13));
  for (const args of [[],['context-packet.js'],['context-packet.js',input,'extra']]) {
    result=spawnSync(process.execPath,args,{encoding:'utf8'});
    assert.equal(result.status,2); assert.equal(result.stdout,''); assert.notEqual(result.stderr,'');
  }
} finally { fs.rmSync(dir,{recursive:true,force:true}); }
console.log('extended API and CLI assertions passed');
EOF

